            }
            if (!isQueue(input.command)) {
                const queued = parseSuffix(body) ?? ((await automaticallyQueue(sid)) ? { body } : undefined);
                if (!queued)
                    return;
                if (!shouldQueue(sessions.get(sid))) {
                    for (const part of output.parts)
                        if (part.type === "text")
                            part.text = stripSuffix(part.text);
                    return;
                }
                output.parts.splice(0, output.parts.length, { type: "text", text: `/queue${queued.modifier === "front" ? " front" : ""} /${input.command}${queued.body.trim() ? ` ${queued.body.trim()}` : ""}` }, ...parts);
                return;
            }
            const request = parsePrefix(body);
            const op = parse(request, parts.length);
            if (control(op))
                return stop(await afterEnqueue(sid, () => manage(sid, op)));
            if (op.kind === "invalid")
                return stop(op.message, "error");
            if (!shouldQueue(sessions.get(sid)) || (request.modifier === "now" && op.kind !== "prompt" && op.kind !== "shell")) {
                if (op.kind === "shell") {
                    await shell(sid, op.shell, await run(sid));
                    return handled();
                }
                if (op.kind === "compact") {
                    await client.tui.executeCommand({ body: { command: TUI_COMPACT }, throwOnError: true });
                    return handled();
                }
                if (op.kind === "command") {
                    await callCommand(sid, op.cmd, op.args, () => client.session.command({ path: { id: sid }, body: { command: op.cmd, arguments: op.args, parts } }));
                    return handled();
                }
                output.parts.splice(0, output.parts.length, { type: "text", text: op.body }, ...parts);
                return;
            }
            output.parts.splice(0, output.parts.length, { type: "text", text: `/queue ${body}` }, ...parts);
        },
        "chat.message": async (input, output) => {
            const sid = input.sessionID;
            if (deleted.has(sid)) {
                console.warn("QueuePlugin ignored input for a deleted session", sid);
                return;
            }
            const internal = output.parts.find((part) => part.type === "text" && part.metadata?.[INTERNAL] === origin);
            if (internal) {
                delete internal.metadata[INTERNAL];
                return;
            }
            const text = output.parts.find((part) => part.type === "text" && !part.synthetic);
            if (!text)
                return;
            const request = parseInput(text.text) ?? ((await automaticallyQueue(sid)) ? { body: text.text } : undefined);
            if (!request)
                return;
            const current = state(sid);
            const parts = files(output.parts);
            const op = parse(request, parts.length);
            const info = { agent: input.agent ?? output.message.agent, model: input.model ?? output.message.model, variant: input.variant };
            const placeholder = { id: output.message.id, part: text };
            if (control(op)) {
                await toast(await afterEnqueue(sid, () => manage(sid, op, placeholder)), "info", 5000);
                return;
            }
            if (op.kind === "invalid") {
                await persist(sid, placeholder, () => undefined);
                await toast(op.message, "error", 5000);
                return;
            }
            if ((request.modifier === "now" && op.kind !== "shell") || !shouldQueue(current)) {
                if (op.kind === "command")
                    return;
                if (op.kind === "compact") {
                    await persist(sid, placeholder, () => undefined);
                    await compact(sid, info);
                    return;
                }
                if (op.kind === "shell") {
                    await persist(sid, placeholder, () => undefined);
                    await shell(sid, op.shell, info);
                    return;
                }
                text.text = request.body;
                return;
            }
            return orderedEnqueue(sid, async () => {
                if (deleted.has(sid)) {
                    console.warn("QueuePlugin stopped queueing input for a deleted session", sid);
                    return;
                }
                const prior = await latest(sid);
                if (deleted.has(sid)) {
                    console.warn("QueuePlugin stopped queueing input for a deleted session", sid);
                    return;
                }
                if (prior)
                    Object.assign(output.message, opts(prior));
                else
                    console.warn("QueuePlugin could not neutralize queued placeholder metadata because the session has no previous message context");
                let item;
                if (op.kind === "shell")
                    item = { kind: "shell", info, source: op.source, shell: op.shell };
                else if (op.kind === "compact")
                    item = { kind: "compact", info, source: op.source };
                else if (op.kind === "command")
                    item = { kind: "command", info, source: op.source, cmd: op.cmd, args: op.args, files: parts };
                else {
                    item = {
                        kind: "prompt",
                        info,
                        body: op.body,
                        parts: output.parts.flatMap((part) => {
                            if (part.type === "text")
                                return part.id === text.id ? (request.body ? [{ ...part, text: request.body }] : []) : [{ ...part }];
                            if (part.type === "file" || part.type === "agent" || part.type === "subtask")
                                return [{ ...part }];
                            console.warn("QueuePlugin skipped unexpected part", part.type);
                            return [];
                        }),
                    };
                }
                await persist(sid, placeholder, (draft) => {
                    if (op.front)
                        draft.items.unshift(item);
                    else
                        draft.items.push(item);
                });
                advance(sid);
                await toast(`${op.front ? "Queued first" : "Queued"}: ${itemText(item)}`, "info");
            });
        },
        "experimental.chat.messages.transform": async (_, output) => {
            output.messages = output.messages.filter((msg) => {
                for (const current of sessions.values())
                    if (current.hidden.has(msg.info.id))
                        return false;
                return true;
            });
        },
    };
    return hooks;
};
export default QueuePlugin;
